	Win *win = vis->win;
	if (!old->visual && win) {
		for (Selection *s = view_selections(&win->view); s; s = view_selections_next(s))
			s->anchored = true;
	}
}

static void vis_mode_visual_line_enter(Vis *vis, Mode *old) {
	Win *win = vis->win;
	if (!old->visual && win) {
		for (Selection *s = view_selections(&win->view); s; s = view_selections_next(s))
			s->anchored = true;
