static int ui_newindex(lua_State *L) {
	Ui *ui = obj_ref_check(L, 1,  VIS_LUA_TYPE_UI);

	if (lua_isstring(L, 2)) {
		const char *key  = lua_tostring(L, 2);

		if (strcmp(key, "layout") == 0) {
			ui_arrange(ui, luaL_checkinteger(L, 3));
			return 0;
		}
	}
	return newindex_common(L);
}

static const struct luaL_Reg ui_funcs[] = {
	{ "__index", ui_index },
	{ "__newindex", ui_newindex },
	{ NULL, NULL },
};

static int registers_index(lua_State *L) {
	lua_newtable(L);
	Vis *vis = lua_touserdata(L, lua_upvalueindex(1));
	const char *symbol = luaL_checkstring(L, 2);
	if (strlen(symbol) != 1)
		return 1;
	enum VisRegister reg = vis_register_from(vis, symbol[0]);
	if (reg >= VIS_REG_INVALID)
		return 1;
	str8_list strings = vis_register_get(vis, reg);
	for (VisDACount i = 0; i < strings.count; i++) {
		str8 string = strings.data[i];
		lua_pushinteger(L, i+1);
		lua_pushlstring(L, (char *)string.data, string.length);
		lua_settable(L, -3);
	}
	da_release(&strings);
	return 1;
}

static int registers_newindex(lua_State *L) {
	Vis *vis = lua_touserdata(L, lua_upvalueindex(1));
	const char *symbol = luaL_checkstring(L, 2);
	if (strlen(symbol) != 1)
		return 0;
	enum VisRegister reg = vis_register_from(vis, symbol[0]);

	str8_list strings = {0};
	if (lua_istable(L, 3)) {
		lua_pushnil(L);
		while (lua_next(L, 3)) {
			size_t length;
			str8   string;
			string.data   = (uint8_t *)luaL_checklstring(L, -1, &length);
			string.length = (ptrdiff_t)length;
			*da_push(vis, &strings) = string;
			lua_pop(L, 1);
		}
	}

	vis_register_set(vis, reg, strings);
	da_release(&strings);
	return 0;
}

static int registers_len(lua_State *L) {
	Vis *vis = lua_touserdata(L, lua_upvalueindex(1));
	lua_pushinteger(L, LENGTH(vis->registers));
	return 1;
}

